public void testGetPositionAfterMove() {
    // Move to the next position
    iterator.next();
    // Get the current position
    int position = iterator.getPosition();
    // Move to the previous position
    iterator.previous();
    // Position should be 0
    Assert.assertEquals(0, position);
}

